part of 'agent_cli.dart';

// The `/cube` command family (fa_cube Phase 1): line-mode status and live
// management of the session's sandbox profile over [_cubeEnv]. Output is
// plain `io.writeln` lines, styled like the other info commands — no TUI
// picker. The settings-hub Cube sandbox flow shares the resolve/apply/
// deactivate helpers below so the switch logic lives in one place.

/// Usage line printed for an unknown `/cube` subcommand.
const String _cubeUsage =
    'usage: /cube [list | use <name-or-path> [--allow-degrade] | off | '
    'reload | templates | install <id> | cache status | cache clear]';

/// The web-egress network gate (issue #682) handed to the web tools;
/// reads the LIVE cube spec per call. Null only on hosts that build the
/// tool set without one (`/cube` status then reports `n/a`).
///
/// Reads the LIVE spec per call, so `/cube use` / `/cube off` are honored
/// by the next web tool call; null spec (no cube) is allow-all.
CubeNetworkGate _initWebNetworkGate(SandboxedExecutionEnv cubeEnv) =>
    CubeNetworkGate(() => cubeEnv.activeSpec);

/// The `/cube` command family on [AgentCli].
extension CubeCommands on AgentCli {
  /// Dispatches `/cube` and its subcommands.
  Future<void> _handleCubeCommand(String rest) async {
    final parts = rest.isEmpty ? const <String>[] : rest.split(RegExp(r'\s+'));
    final sub = parts.isEmpty ? null : parts.first;
    if (sub == null) return _printCubeStatus();
    if (sub == 'cache') return _handleCubeCacheCommand(parts);
    if (sub == 'templates') return _cubeTemplates();
    if (sub == 'install') return _cubeInstall(parts.skip(1).join(' '));
    switch (sub) {
      case 'list':
        await _cubeList();
      case 'use':
        await _cubeUse(parts.skip(1).join(' '));
      case 'off':
        _cubeOff();
      case 'reload':
        await _cubeReload();
      default:
        io.writeln(_cubeUsage);
    }
  }

  /// `/cube cache [clear]` — cache status or a best-effort invalidation.
  Future<void> _handleCubeCacheCommand(List<String> parts) async {
    if (parts.length > 1 && parts[1] == 'clear') {
      await _cubeCacheClear();
    } else {
      _printCubeCacheStatus();
    }
  }

  /// The bare `/cube` branch: the active profile's identity, backend,
  /// policy summary and cache — or the disabled note.
  void _printCubeStatus() {
    final spec = _cubeEnv.activeSpec;
    if (spec == null) {
      io.writeln('cube: disabled (full host access)');
      io.writeln('  network gate: $_networkGateStatus');
      return;
    }
    final description = spec.description;
    io.writeln(
      'cube: ${spec.name}${description == null ? '' : ' — $description'}',
    );
    final osName = config.osName;
    io.writeln(
      '  backend: '
      '${osName == null ? 'host passthrough' : cubeBackendForPlatform(osName).describe()}'
      '${spec.allowDegrade ? ' (policy degrade allowed)' : ''}',
    );
    final allow = spec.tools.allow.toList()..sort();
    io.writeln(
      '  tools allow: ${allow.isEmpty ? '(none — every command denied)' : allow.join(', ')}',
    );
    final deny = spec.tools.deny.toList()..sort();
    if (deny.isNotEmpty) io.writeln('  tools deny: ${deny.join(', ')}');
    final hosts = [for (final rule in spec.network.allow) rule.host];
    io.writeln(
      '  network allow: ${hosts.isEmpty ? '(none — all network denied)' : hosts.join(', ')}',
    );
    io.writeln('  network gate: $_networkGateStatus');
    io.writeln('  cache: ${_cubeCacheLine(spec)}');
  }

  /// The `network gate:` status value (issue #682): `on` under an active
  /// cube, `off` in passthrough (allow-all), `n/a` when this host runs
  /// the web tools without a gate.
  String get _networkGateStatus => _webNetworkGate == null
      ? 'n/a'
      : _cubeEnv.activeSpec == null
      ? 'off'
      : 'on';

  /// `/cube list` — the cube manifests available for this project plus the
  /// built-in security-level presets.
  Future<void> _cubeList() async {
    final dir = '${_env.cwd}/.fah/cubes';
    final names = await _projectCubeNames();
    if (names == null) {
      io.writeln('cube: no cubes directory ($dir)');
      return;
    }
    if (names.isEmpty) {
      io.writeln('cube: no cubes in $dir');
    }
    for (final name in names) {
      io.writeln('  $name');
    }
    if (names.isNotEmpty) io.writeln('');
    io.writeln('built-in presets (usable with /cube use <id>):');
    for (final preset in CubePresets.all) {
      io.writeln('  ${preset.id} — ${preset.title}: ${preset.description}');
    }
  }

  /// `/cube use <name-or-path>` — resolve a manifest and enforce it from now
  /// on. A target containing `/` is a path, anything else a cube name.
  Future<void> _cubeUse(String args) async {
    var target = args.trim();
    // SEC-05 escape hatch: `/cube use <preset> --allow-degrade` opts a
    // kernel spec into policy-mode fallback on hosts without an
    // enforcing backend. Explicit per invocation, remembered for reload.
    var allowDegrade = false;
    if (target.endsWith('--allow-degrade')) {
      allowDegrade = true;
      target = target
          .substring(0, target.length - '--allow-degrade'.length)
          .trim();
    }
    if (target.isEmpty) {
      io.writeln('usage: /cube use <name-or-path> [--allow-degrade]');
      return;
    }
    final resolved = await _resolveCubeTarget(target);
    if (resolved == null) return;
    final spec = allowDegrade ? resolved.withAllowDegrade() : resolved;
    _cubeUseAllowDegrade = allowDegrade;
    await _activateCube(spec, target);
    io.writeln(
      'cube: ${spec.name} active'
      '${allowDegrade ? ' (policy degrade allowed)' : ''}',
    );
  }

  /// `/cube off` — leave sandbox mode; every operation forwards untouched.
  void _cubeOff() {
    if (_cubeEnv.activeSpec == null) {
      io.writeln('cube: already off (full host access)');
      return;
    }
    _deactivateCube();
    io.writeln('cube: off (full host access)');
  }

  /// `/cube reload` — re-resolve the remembered source (boot flag/config or
  /// the last `/cube use`) and enforce it again.
  Future<void> _cubeReload() async {
    final source = _cubeSource;
    if (source == null) {
      io.writeln('cube: no source to reload (use /cube use <name-or-path>)');
      return;
    }
    final resolved = await _resolveCubeTarget(source);
    if (resolved == null) return;
    await _activateCube(
      _cubeUseAllowDegrade ? resolved.withAllowDegrade() : resolved,
      source,
    );
    io.writeln('cube: ${resolved.name} reloaded');
  }

  /// `/cube templates` — the fa1.dev registry catalog.
  Future<void> _cubeTemplates() async {
    final templates = await _cubeRegistryTemplates();
    if (templates == null) return;
    io.writeln(
      'cube registry (${_registryClient.baseUrl}): '
      '${templates.length} template${templates.length == 1 ? '' : 's'}',
    );
    for (final template in templates) {
      io.writeln(
        '  ${template.id} — ${template.name}: '
        '${template.description}',
      );
    }
  }

  /// `/cube install <id>` — download the template manifest, verify its
  /// sha256 and write it to `.fah/cubes/<id>.yaml`.
  Future<void> _cubeInstall(String id) async {
    if (id.isEmpty) {
      io.writeln('usage: /cube install <template-id>');
      return;
    }
    final templates = await _cubeRegistryTemplates();
    if (templates == null) return;
    final matches = templates.where((t) => t.id == id).toList();
    if (matches.isEmpty) {
      io.writeln(
        'cube registry: no template "$id" — '
        '${templates.length} available, try /cube templates',
      );
      return;
    }
    final template = matches.single;
    final String yaml;
    try {
      yaml = await _registryClient.download(template);
    } on ConfigException catch (error) {
      io.writeln(error.message);
      return;
    }
    final path = '${_env.cwd}/.fah/cubes/${template.id}.yaml';
    final write = await _env.writeFile(path, yaml);
    if (write is Err) {
      io.writeln('cube: cannot write $path');
      return;
    }
    io.writeln(
      'cube: installed $path '
      '(sha256 ${template.sha256.substring(0, 8)}…) — '
      'apply it with /cube use ${template.id}',
    );
  }

  /// The registry client: fa1.dev by default, the host/test client
  /// injected through [AgentCliConfig.cubeRegistryClient].
  CubeRegistryClient get _registryClient => CubeRegistryClient(
    baseUrl: CubeRegistryClient.defaultBaseUrl,
    client: config.cubeRegistryClient,
  );

  /// Fetches the registry catalog; null (after a clean error line) on any
  /// failure — a broken registry never crashes the REPL.
  Future<List<CubeRegistryTemplate>?> _cubeRegistryTemplates() async {
    try {
      return await _registryClient.templates();
    } on ConfigException catch (error) {
      io.writeln(error.message);
      return null;
    }
  }

  /// `/cube cache status` — key, root and policy of the active cube's cache.
  void _printCubeCacheStatus() {
    final spec = _cubeEnv.activeSpec;
    if (spec == null) {
      io.writeln('cube: no cube active');
      return;
    }
    final manager = CubeCacheManager(_cubeEnv, spec);
    io.writeln('cube cache key: ${manager.cacheKey}');
    io.writeln('  root: ${manager.cacheRoot}');
    io.writeln('  ${_cubeCacheLine(spec)}');
  }

  /// `/cube cache clear` — drop the active cube's cache entry.
  Future<void> _cubeCacheClear() async {
    final spec = _cubeEnv.activeSpec;
    if (spec == null) {
      io.writeln('cube: no cube active');
      return;
    }
    final manager = CubeCacheManager(_cubeEnv, spec);
    await manager.clear();
    io.writeln('cube cache cleared (${manager.cacheRoot})');
  }

  /// Best-effort cache restore: one warning line on failure, never a crash.
  Future<void> _cubeRestoreQuietly(CubeSpec spec) async {
    try {
      await CubeCacheManager(_cubeEnv, spec).restoreIfNeeded();
    } on Object catch (error) {
      io.writeln('cube: cache restore failed: $error');
    }
  }

  /// One-line cache summary: content key plus enabled/restore/ttl.
  String _cubeCacheLine(CubeSpec spec) {
    final ttl = spec.cache.ttl;
    return 'key ${CubeCacheManager(_cubeEnv, spec).cacheKey}, '
        '${spec.cache.enabled ? 'enabled' : 'disabled'}, '
        'restore ${spec.cache.restore ? 'on' : 'off'}'
        '${ttl == null ? '' : ', ttl ${ttl.inSeconds}s'}';
  }

  /// The cube names under `<cwd>/.fah/cubes/*.yaml`, sorted. Null when the
  /// directory is missing, empty when it holds no manifests — shared by
  /// `/cube list` and the settings-hub Cube sandbox flow.
  Future<List<String>?> _projectCubeNames() async {
    final listing = await _env.listDir('${_env.cwd}/.fah/cubes');
    switch (listing) {
      case Err():
        return null;
      case Ok(:final value):
        return [
          for (final entry in value)
            if (entry.kind == FileKind.file && entry.name.endsWith('.yaml'))
              entry.name.substring(0, entry.name.length - '.yaml'.length),
        ]..sort();
    }
  }

  /// Resolves a cube name-or-path to a spec: a target containing `/` is a
  /// manifest path, anything else a cube name. Returns null (after printing
  /// the resolver error) when the manifest cannot be loaded — shared by
  /// `/cube use`, `/cube reload` and the settings-hub Cube sandbox flow.
  Future<CubeSpec?> _resolveCubeTarget(String target) async {
    try {
      final isPath = target.contains('/');
      return await CubeResolver.resolve(
        env: _env,
        path: isPath ? target : null,
        name: isPath ? null : target,
        homeDir: config.homeDir,
      );
    } on ConfigException catch (error) {
      io.writeln(error.message);
      return null;
    }
  }

  /// Enforces [spec] from now on: swaps the sandbox spec, remembers
  /// [source] for `/cube reload` and restores the cache — shared by
  /// `/cube use`, `/cube reload` and the settings-hub Cube sandbox flow.
  Future<void> _activateCube(CubeSpec spec, String source) async {
    _cubeEnv.updateSpec(spec);
    _cubeSource = source;
    await _cubeRestoreQuietly(spec);
  }

  /// Leaves sandbox mode: every operation forwards untouched — shared by
  /// `/cube off` and the settings-hub Cube sandbox flow.
  void _deactivateCube() {
    _cubeEnv.clearSpec();
  }

  /// The current sandbox state as a short label: the active cube name or
  /// the disabled note (settings-hub row and the line-mode summary).
  String _cubeStatusLabel() {
    final spec = _cubeEnv.activeSpec;
    return spec == null ? 'disabled (full host access)' : spec.name;
  }

  /// Settings → Cube sandbox: pick disabled, one of the project's
  /// `.fah/cubes/*.yaml` manifests, or a custom path. The pick applies live
  /// through the same helpers as `/cube use`/`/cube off` and persists as
  /// the startup default (`cube:` section) in the user config.
  Future<void> startCubeSandboxFlow() async {
    final picked = await _pickOption(
      'cube sandbox',
      await _cubeSandboxOptions(),
    );
    if (picked == null) return;
    if (picked == _cubePickCustom) {
      final path = await _askLine('cube manifest path (empty cancels): ');
      final trimmed = path?.trim() ?? '';
      if (trimmed.isEmpty) return;
      await _applyCubeSelection(trimmed);
      return;
    }
    await _applyCubeSelection(picked == _cubePickOff ? null : picked);
  }

  /// The Cube sandbox picker rows: disabled, every project manifest (the
  /// key is the relative path the default saves, the label the file stem),
  /// the built-in security-level presets, and the custom-path escape.
  Future<List<(String, String, String)>> _cubeSandboxOptions() async {
    final active = _cubeEnv.activeSpec?.name;
    final names = await _projectCubeNames();
    return [
      (
        _cubePickOff,
        'disabled (full host access)',
        active == null ? 'current' : 'currently $active',
      ),
      if (names != null)
        for (final name in names)
          ('.fah/cubes/$name.yaml', name, 'project cube manifest'),
      for (final preset in CubePresets.all)
        (preset.id, preset.title, preset.description),
      (_cubePickCustom, 'custom path...', 'enter a manifest path'),
    ];
  }

  /// Applies a Cube sandbox selection end to end: [target] null disables
  /// the sandbox, anything else resolves (name or path) and enforces it —
  /// then either way the choice persists as the startup default.
  Future<void> _applyCubeSelection(String? target) async {
    if (target == null) {
      _deactivateCube();
      io.writeln('cube: off (full host access)');
    } else {
      final spec = await _resolveCubeTarget(target);
      if (spec == null) return;
      await _activateCube(spec, target);
      io.writeln('cube: ${spec.name} active');
    }
    await _persistCubeDefault(target);
  }

  /// Records [target] as the saved `cube:` startup default (null records
  /// `enabled: false`) through the host's persistence hook. Hosts without
  /// one (tests, web) keep the change session-only.
  Future<void> _persistCubeDefault(String? target) async {
    final persist = config.onCubeSettingsChanged;
    config.cubeSettings = target == null
        ? const CubeSettings(enabled: false)
        : CubeSettings(configPath: target);
    if (persist == null) {
      io.writeln('cube: default kept for this session only (no user config)');
      return;
    }
    await persist();
    io.writeln('cube: saved default ${target ?? '(disabled)'}');
  }

  /// Cube cache restore before the first turn — best-effort (one warning
  /// line on failure, never a blocker).
  Future<void> _cubeBootRestore() async {
    final bootSpec = _cubeEnv.activeSpec;
    if (bootSpec != null) await _cubeRestoreQuietly(bootSpec);
  }

  /// Cube cache save mirroring [run]'s exit path (best-effort).
  Future<void> _cubeCacheSaveQuietly() async {
    final exitSpec = _cubeEnv.activeSpec;
    if (exitSpec != null) {
      try {
        await CubeCacheManager(_cubeEnv, exitSpec).save();
      } on Object catch (error) {
        io.writeln('cube: cache save failed: $error');
      }
    }
  }
}

/// Picker keys of the settings-hub Cube sandbox flow (cube rows are keyed
/// by their relative manifest path, so no key can collide).
const String _cubePickOff = 'off';

const String _cubePickCustom = 'custom';

/// The cube manifest itself (`CubeSpec`): a declarative sandbox profile
/// parsed from a strict yaml document.
///
/// ```yaml
/// apiVersion: fa/v1          # required, exactly 'fa/v1'
/// kind: Cube                 # required, exactly 'Cube'
/// metadata:
///   name: web-scraper        # required, ^[a-z][a-z0-9-]*$
///   description: "..."       # optional
/// spec:
///   tools: ...
///   backend: policy           # optional, 'policy' (default) | 'kernel'
///   network: ...
///   filesystem: ...
///   env: ...
///   resources: ...
///   cache: ...
/// ```
///
/// Parsing is strict: any schema problem (wrong apiVersion/kind, bad name,
/// unknown keys at any level) throws [ConfigException] naming the YAML path.
/// A missing `spec:` section yields the safe defaults: deny-all tools,
/// deny-all network, workspace `/workspace`, empty env, no resource limits,
/// disabled cache.
///
/// [CubeSpec.toCanonicalMap] renders the whole spec as a stable
/// JSON-encodable map (sorted keys, sorted lists, durations as seconds) for
/// the content-addressed cache key.
library;

import 'package:yaml/yaml.dart';

import '../../exceptions.dart';

import 'cache_policy.dart';
import 'env_policy.dart';
import 'fs_policy.dart';
import 'network_policy.dart';
import 'resource_limits.dart';
import 'tool_policy.dart';

final RegExp _namePattern = RegExp(r'^[a-z][a-z0-9-]*$');

/// How commands are confined: `policy` (the Phase 1 default) or `kernel`
/// (wrapped in the OS sandbox primitive of the host platform —
/// sandbox-exec on macOS, unshare on Linux).
enum CubeBackendMode {
  /// Dart policy layers only — the Phase 1 default.
  policy,

  /// OS kernel confinement for the host platform, on top of the Dart
  /// layers. On a platform without an enforcing backend a kernel spec is
  /// REFUSED (fail-closed) unless the spec opts into the fallback via
  /// [CubeSpec.allowDegrade].
  kernel;

  /// Parses the `spec.backend:` label, throwing [ConfigException] on an
  /// unknown value.
  static CubeBackendMode parse(Object? node, String where) => switch (node) {
    null => policy,
    'policy' => policy,
    'kernel' => kernel,
    _ => throw ConfigException(
      '$where.backend: must be "policy" or "kernel", got $node',
    ),
  };
}

/// A parsed cube manifest: identity plus the five policy sections.
final class CubeSpec {
  /// Creates a spec; policies default to their safe values.
  const CubeSpec({
    required this.name,
    this.description,
    this.backend = CubeBackendMode.policy,
    this.allowDegrade = false,
    this.tools = const CubeToolPolicy(),
    this.network = const CubeNetworkPolicy(),
    this.filesystem = const CubeFsPolicy(),
    this.env = const CubeEnvPolicy(),
    this.resources = const CubeResourceLimits(),
    this.cache = const CubeCachePolicy(),
  });

  /// Cube name, `^[a-z][a-z0-9-]*$` (enforced at parse).
  final String name;

  /// Optional human-readable description.
  final String? description;

  /// How commands are confined — Dart policy layers only, or wrapped in
  /// the host platform's kernel sandbox.
  final CubeBackendMode backend;

  /// Whether an unavailable `backend: kernel` may degrade to policy mode.
  /// Requested isolation is a contract: without this opt-in a kernel spec
  /// on a platform without an enforcing backend is REFUSED (zero commands
  /// run); with it the shell degrades loudly (`onDegrade`) and reports the
  /// effective backend for audit.
  final bool allowDegrade;

  /// A copy of this spec with [allowDegrade] set — the `/cube use
  /// --allow-degrade` opt-in path (SEC-05: degrade only via explicit
  /// opt-in, never silently).
  CubeSpec withAllowDegrade({bool allowDegrade = true}) => CubeSpec(
    name: name,
    description: description,
    backend: backend,
    allowDegrade: allowDegrade,
    tools: tools,
    network: network,
    filesystem: filesystem,
    env: env,
    resources: resources,
    cache: cache,
  );

  /// Which command words may run.
  final CubeToolPolicy tools;

  /// Which hosts/ports may be reached.
  final CubeNetworkPolicy network;

  /// Which paths may be read or written.
  final CubeFsPolicy filesystem;

  /// Which environment variables the run sees.
  final CubeEnvPolicy env;

  /// Resource caps and timeout.
  final CubeResourceLimits resources;

  /// Cache behavior.
  final CubeCachePolicy cache;

  /// Parses a whole cube yaml document. [sourcePath] names the document in
  /// error messages (default `'cube'`).
  factory CubeSpec.fromYaml(Object? node, {String sourcePath = 'cube'}) {
    if (node is! YamlMap) {
      throw ConfigException(
        '$sourcePath: must be a yaml map, got ${node.runtimeType}',
      );
    }
    _checkKeys(node, const {
      'apiVersion',
      'kind',
      'metadata',
      'spec',
    }, sourcePath);
    final apiVersion = node['apiVersion'];
    if (apiVersion != 'fa/v1') {
      throw ConfigException(
        '$sourcePath.apiVersion: must be exactly "fa/v1", got $apiVersion',
      );
    }
    final kind = node['kind'];
    if (kind != 'Cube') {
      throw ConfigException(
        '$sourcePath.kind: must be exactly "Cube", got $kind',
      );
    }
    final metadata = node['metadata'];
    if (metadata is! YamlMap) {
      throw ConfigException(
        '$sourcePath.metadata: must be a map with a "name", '
        'got ${metadata.runtimeType}',
      );
    }
    _checkKeys(metadata, const {'name', 'description'}, '$sourcePath.metadata');
    final name = metadata['name'];
    if (name is! String || !_namePattern.hasMatch(name)) {
      throw ConfigException(
        '$sourcePath.metadata.name: must match ^[a-z][a-z0-9-]*\$, '
        'got $name',
      );
    }
    final description = metadata['description'];
    if (description != null && description is! String) {
      throw const ConfigException(
        'cube.metadata.description: must be a string',
      );
    }
    final spec = node['spec'];
    if (spec != null && spec is! YamlMap) {
      throw ConfigException(
        '$sourcePath.spec: must be a map, got ${spec.runtimeType}',
      );
    }
    _checkKeys(spec, const {
      'backend',
      'allowDegrade',
      'tools',
      'network',
      'filesystem',
      'env',
      'resources',
      'cache',
    }, '$sourcePath.spec');
    final allowDegrade = spec?['allowDegrade'];
    if (allowDegrade != null && allowDegrade is! bool) {
      throw ConfigException(
        '$sourcePath.spec.allowDegrade: must be a boolean, got $allowDegrade',
      );
    }
    return CubeSpec(
      name: name,
      description: description,
      backend: CubeBackendMode.parse(spec?['backend'], '$sourcePath.spec'),
      allowDegrade: allowDegrade ?? false,
      tools: CubeToolPolicy.fromYaml(spec?['tools']),
      network: CubeNetworkPolicy.fromYaml(spec?['network']),
      filesystem: CubeFsPolicy.fromYaml(spec?['filesystem']),
      env: CubeEnvPolicy.fromYaml(spec?['env']),
      resources: CubeResourceLimits.fromYaml(spec?['resources']),
      cache: CubeCachePolicy.fromYaml(spec?['cache']),
    );
  }

  /// A stable, JSON-encodable canonical form of the whole spec: keys sorted
  /// at every level, lists sorted (semantically orderless), durations as
  /// seconds, `null` fields omitted. Two specs that parse to the same
  /// policy always produce an equal map — this is the content-addressed
  /// cache key input.
  Map<String, Object?> toCanonicalMap() {
    return {
      'apiVersion': 'fa/v1',
      'kind': 'Cube',
      'metadata': {
        if (description != null) 'description': description,
        'name': name,
      },
      'spec': {
        'backend': backend.name,
        // Omitted when false so existing specs keep byte-identical cache
        // keys.
        if (allowDegrade) 'allowDegrade': true,
        'cache': {
          'enabled': cache.enabled,
          if (cache.paths.isNotEmpty) 'paths': [...cache.paths]..sort(),
          'restore': cache.restore,
          if (cache.ttl != null) 'ttl': cache.ttl!.inSeconds,
        },
        'env': [
          for (final variable in [...env.vars]..sort(_byName))
            switch (variable) {
              CubeEnvValue(:final name, :final value) => {
                'name': name,
                'value': value,
              },
              CubeEnvValueFrom(:final name, :final source) => {
                'name': name,
                'valueFrom': source,
              },
              CubeEnvHidden(:final name) => {'hidden': true, 'name': name},
            },
        ],
        'filesystem': {
          'mounts': [
            for (final mount in [...filesystem.mounts]..sort(_byPath))
              {'access': mount.access.label, 'path': mount.path},
          ],
          'workspace': filesystem.workspace,
        },
        'network': {
          'allow': [
            for (final rule in [...network.allow]..sort(_byHost))
              _canonicalRule(rule),
          ],
          'deny': [
            for (final rule in [...network.deny]..sort(_byHost))
              _canonicalRule(rule),
          ],
        },
        'resources': {
          if (resources.cpu != null) 'cpu': resources.cpu,
          if (resources.diskBytes != null) 'diskBytes': resources.diskBytes,
          if (resources.memoryBytes != null)
            'memoryBytes': resources.memoryBytes,
          if (resources.timeout != null)
            'timeout': resources.timeout!.inSeconds,
        },
        'tools': {
          'allow': [...tools.allow]..sort(),
          'deny': [...tools.deny]..sort(),
        },
      },
    };
  }

  static Map<String, Object?> _canonicalRule(CubeNetworkRule rule) {
    final ports = rule.ports;
    return {
      'host': rule.host,
      if (ports != null && ports.isNotEmpty) 'ports': ports.toList()..sort(),
    };
  }

  static int _byName(CubeEnvVar a, CubeEnvVar b) => a.name.compareTo(b.name);

  static int _byPath(CubeMount a, CubeMount b) => a.path.compareTo(b.path);

  static int _byHost(CubeNetworkRule a, CubeNetworkRule b) =>
      a.host.compareTo(b.host);

  static void _checkKeys(YamlMap? node, Set<String> allowed, String where) {
    for (final key in node?.keys ?? const Iterable<Object?>.empty()) {
      if (key is! String || !allowed.contains(key)) {
        throw ConfigException(
          '$where: unknown key "$key" — supported: ${allowed.join(', ')}',
        );
      }
    }
  }
}

