apiVersion: fa/v1
kind: Cube
metadata:
  name: strict
spec:
  tools:
    allow: [ls]
''';

  /// Writes a cube manifest under `<cwd>/.fah/cubes/`.
  Future<void> writeCube(String name, String yaml) async {
    await env.writeFile('/work/.fah/cubes/$name.yaml', yaml);
  }

