        .split('\n')
        .firstWhere((line) => line.startsWith('$wrapper: '), orElse: () => '');
    if (complaint.isNotEmpty) {
      return (
        note:
            '$wrapper failed: '
            '${complaint.substring('$wrapper: '.length)}',
        cause: value.stderr,
