part of 'agent_cli.dart';

// The `/cube` command family (fa_cube Phase 1): line-mode status and live
// management of the session's sandbox profile over [_cubeEnv]. Output is
// plain `io.writeln` lines, styled like the other info commands — no TUI
// picker. The settings-hub Cube sandbox flow shares the resolve/apply/
// deactivate helpers below so the switch logic lives in one place.

/// Usage line printed for an unknown `/cube` subcommand.
const String _cubeUsage =
    'usage: /cube [list | use <name-or-path> [--allow-degrade] | off | '
    'reload | templates | install <id> | cache status | cache clear]';

/// The web-egress network gate (issue #682) handed to the web tools;
/// reads the LIVE cube spec per call. Null only on hosts that build the
/// tool set without one (`/cube` status then reports `n/a`).
///
/// Reads the LIVE spec per call, so `/cube use` / `/cube off` are honored
/// by the next web tool call; null spec (no cube) is allow-all.
CubeNetworkGate _initWebNetworkGate(SandboxedExecutionEnv cubeEnv) =>
    CubeNetworkGate(() => cubeEnv.activeSpec);

/// The `/cube` command family on [AgentCli].
extension CubeCommands on AgentCli {
  /// Dispatches `/cube` and its subcommands.
  Future<void> _handleCubeCommand(String rest) async {
    final parts = rest.isEmpty ? const <String>[] : rest.split(RegExp(r'\s+'));
    final sub = parts.isEmpty ? null : parts.first;
    if (sub == null) return _printCubeStatus();
    if (sub == 'cache') return _handleCubeCacheCommand(parts);
    if (sub == 'templates') return _cubeTemplates();
    if (sub == 'install') return _cubeInstall(parts.skip(1).join(' '));
    switch (sub) {
      case 'list':
        await _cubeList();
      case 'use':
        await _cubeUse(parts.skip(1).join(' '));
      case 'off':
        _cubeOff();
      case 'reload':
        await _cubeReload();
      default:
        io.writeln(_cubeUsage);
    }
  }

  /// `/cube cache [clear]` — cache status or a best-effort invalidation.
  Future<void> _handleCubeCacheCommand(List<String> parts) async {
    if (parts.length > 1 && parts[1] == 'clear') {
      await _cubeCacheClear();
    } else {
      _printCubeCacheStatus();
    }
  }

  /// The bare `/cube` branch: the active profile's identity, backend,
  /// policy summary and cache — or the disabled note.
  void _printCubeStatus() {
    final spec = _cubeEnv.activeSpec;
    if (spec == null) {
      io.writeln('cube: disabled (full host access)');
      io.writeln('  network gate: $_networkGateStatus');
      return;
    }
    final description = spec.description;
    io.writeln(
      'cube: ${spec.name}${description == null ? '' : ' — $description'}',
    );
    final osName = config.osName;
    io.writeln(
      '  backend: '
      '${osName == null ? 'host passthrough' : cubeBackendForPlatform(osName).describe()}'
      '${spec.allowDegrade ? ' (policy degrade allowed)' : ''}',
    );
    final allow = spec.tools.allow.toList()..sort();
    io.writeln(
      '  tools allow: ${allow.isEmpty ? '(none — every command denied)' : allow.join(', ')}',
    );
    final deny = spec.tools.deny.toList()..sort();
    if (deny.isNotEmpty) io.writeln('  tools deny: ${deny.join(', ')}');
    final hosts = [for (final rule in spec.network.allow) rule.host];
    io.writeln(
      '  network allow: ${hosts.isEmpty ? '(none — all network denied)' : hosts.join(', ')}',
    );
    io.writeln('  network gate: $_networkGateStatus');
    io.writeln('  cache: ${_cubeCacheLine(spec)}');
  }

  /// The `network gate:` status value (issue #682): `on` under an active
  /// cube, `off` in passthrough (allow-all), `n/a` when this host runs
  /// the web tools without a gate.
  String get _networkGateStatus => _webNetworkGate == null
      ? 'n/a'
      : _cubeEnv.activeSpec == null
      ? 'off'
      : 'on';

  /// `/cube list` — the cube manifests available for this project plus the
  /// built-in security-level presets.
  Future<void> _cubeList() async {
    final dir = '${_env.cwd}/.fah/cubes';
    final names = await _projectCubeNames();
    if (names == null) {
      io.writeln('cube: no cubes directory ($dir)');
      return;
    }
    if (names.isEmpty) {
      io.writeln('cube: no cubes in $dir');
    }
    for (final name in names) {
      io.writeln('  $name');
    }
    if (names.isNotEmpty) io.writeln('');
    io.writeln('built-in presets (usable with /cube use <id>):');
    for (final preset in CubePresets.all) {
      io.writeln('  ${preset.id} — ${preset.title}: ${preset.description}');
    }
  }

  /// `/cube use <name-or-path>` — resolve a manifest and enforce it from now
  /// on. A target containing `/` is a path, anything else a cube name.
  Future<void> _cubeUse(String args) async {
    var target = args.trim();
    // SEC-05 escape hatch: `/cube use <preset> --allow-degrade` opts a
    // kernel spec into policy-mode fallback on hosts without an
    // enforcing backend. Explicit per invocation, remembered for reload.
    var allowDegrade = false;
    if (target.endsWith('--allow-degrade')) {
      allowDegrade = true;
      target = target
          .substring(0, target.length - '--allow-degrade'.length)
          .trim();
    }
    if (target.isEmpty) {
      io.writeln('usage: /cube use <name-or-path> [--allow-degrade]');
      return;
    }
    final resolved = await _resolveCubeTarget(target);
    if (resolved == null) return;
    final spec = allowDegrade ? resolved.withAllowDegrade() : resolved;
    _cubeUseAllowDegrade = allowDegrade;
    await _activateCube(spec, target);
    io.writeln(
      'cube: ${spec.name} active'
      '${allowDegrade ? ' (policy degrade allowed)' : ''}',
    );
  }

  /// `/cube off` — leave sandbox mode; every operation forwards untouched.
  void _cubeOff() {
    if (_cubeEnv.activeSpec == null) {
      io.writeln('cube: already off (full host access)');
      return;
    }
    _deactivateCube();
    io.writeln('cube: off (full host access)');
  }

  /// `/cube reload` — re-resolve the remembered source (boot flag/config or
  /// the last `/cube use`) and enforce it again.
  Future<void> _cubeReload() async {
    final source = _cubeSource;
    if (source == null) {
      io.writeln('cube: no source to reload (use /cube use <name-or-path>)');
      return;
    }
    final resolved = await _resolveCubeTarget(source);
    if (resolved == null) return;
    await _activateCube(
      _cubeUseAllowDegrade ? resolved.withAllowDegrade() : resolved,
      source,
    );
    io.writeln('cube: ${resolved.name} reloaded');
  }

  /// `/cube templates` — the fa1.dev registry catalog.
  Future<void> _cubeTemplates() async {
    final templates = await _cubeRegistryTemplates();
    if (templates == null) return;
    io.writeln(
      'cube registry (${_registryClient.baseUrl}): '
      '${templates.length} template${templates.length == 1 ? '' : 's'}',
    );
    for (final template in templates) {
      io.writeln(
        '  ${template.id} — ${template.name}: '
        '${template.description}',
      );
    }
  }

  /// `/cube install <id>` — download the template manifest, verify its
  /// sha256 and write it to `.fah/cubes/<id>.yaml`.
  Future<void> _cubeInstall(String id) async {
    if (id.isEmpty) {
      io.writeln('usage: /cube install <template-id>');
      return;
    }
    final templates = await _cubeRegistryTemplates();
    if (templates == null) return;
    final matches = templates.where((t) => t.id == id).toList();
    if (matches.isEmpty) {
      io.writeln(
        'cube registry: no template "$id" — '
        '${templates.length} available, try /cube templates',
      );
      return;
    }
    final template = matches.single;
    final String yaml;
    try {
      yaml = await _registryClient.download(template);
    } on ConfigException catch (error) {
      io.writeln(error.message);
      return;
    }
    final path = '${_env.cwd}/.fah/cubes/${template.id}.yaml';
    final write = await _env.writeFile(path, yaml);
    if (write is Err) {
      io.writeln('cube: cannot write $path');
      return;
    }
    io.writeln(
      'cube: installed $path '
      '(sha256 ${template.sha256.substring(0, 8)}…) — '
      'apply it w…

