      io.sendLine('/cube');
      await waitFor(() => io.out.toString().contains('tools allow:'));
      io.sendLine('/exit');
      await run;

      final out = io.out.toString();
      expect(out, contains('cube: dev active'));
      expect(out, contains('cube: dev — dev sandbox'));

