      network: CubeNetworkPolicy.fromYaml(spec?['network']),
      filesystem: CubeFsPolicy.fromYaml(spec?['filesystem']),
      env: CubeEnvPolicy.fromYaml(spec?['env']),
      resources: CubeResourceLimits.fromYaml(spec?['resources']),
