  /// Parses the `spec.backend:` label, throwing [ConfigException] on an
  /// unknown value.
  static CubeBackendMode parse(Object? node, String where) => switch (node) {
    null => policy,
    'policy' => policy,
    'kernel' => kernel,
    _ => throw ConfigException(
      '$where.backend: must be "policy" or "kernel", got $node',
    ),
  };
}

